WITH _hq_raw AS (SELECT "created_at" AS _hq_row_1, "status" AS _hq_row_2, "amount_cents" AS _hq_row_3, NULL AS _hq_row_4, "status" AS _hq_row_5, NULL AS _hq_row_6 FROM "analytics"."orders" WHERE "tenant_id" = $1),
_hq_source AS (SELECT (CASE WHEN pg_typeof(_hq_row_1) = 'date'::regtype THEN (_hq_row_1)::timestamp AT TIME ZONE 'UTC' ELSE (_hq_row_1)::timestamptz END) AS _hq_time, _hq_row_2 AS _hq_d0, _hq_row_3 AS _hq_v0, _hq_row_4 AS _hq_a0, _hq_row_5 AS _hq_v1, _hq_row_6 AS _hq_a1 FROM _hq_raw WHERE (_hq_row_1 IS NOT NULL)),
_hq_bounds AS (SELECT * FROM (SELECT (CASE WHEN CAST($2 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($2 AS text) AS timestamptz) ELSE CAST(CAST($2 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_lower) AS _hq_step0 CROSS JOIN LATERAL (SELECT (CASE WHEN CAST($3 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($3 AS text) AS timestamptz) ELSE CAST(CAST($3 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_upper) AS _hq_step1 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_lower, 'UTC') AS _hq_first) AS _hq_step2 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_upper, 'UTC') AS _hq_last) AS _hq_step3),
_hq_series AS (SELECT (((_hq_first AT TIME ZONE 'UTC') + (generate_series(0, ((((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_bounds),
_hq_context0 AS (SELECT _hq_period, _hq_period AS _hq_eval_period, (((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_eval_end, GREATEST(_hq_period, _hq_lower) AS _hq_eval_lower, LEAST((((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC'), _hq_upper) AS _hq_eval_upper, (_hq_period > _hq_lower OR TRUE) AS _hq_lower_inclusive, (_hq_upper < (((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AND TRUE) AS _hq_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_history0 AS (SELECT * FROM _hq_source WHERE _hq_time < (SELECT max(_hq_eval_end) FROM _hq_context0)),
_hq_partial0 AS (SELECT _hq_time, _hq_d0, ROW(_hq_d0) AS _hq_partition, SUM(_hq_v0) AS _hq_partial FROM _hq_history0 GROUP BY _hq_time, _hq_d0),
_hq_leaf0 AS (SELECT _hq_time, _hq_partition, SUM(_hq_partial) OVER (PARTITION BY _hq_partition ORDER BY _hq_time ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS _hq_value0 FROM _hq_partial0),
_hq_ranges1 AS (SELECT _hq_period, _hq_eval_lower AS _hq_scan_lower, _hq_eval_upper AS _hq_scan_upper, _hq_lower_inclusive AS _hq_scan_lower_inclusive, _hq_upper_inclusive AS _hq_scan_upper_inclusive FROM _hq_context0),
_hq_keys1 AS (SELECT *, (((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (GREATEST(0, (((date_trunc('day', _hq_scan_upper, 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CASE WHEN _hq_scan_upper > date_trunc('day', _hq_scan_upper, 'UTC') OR _hq_scan_upper_inclusive THEN 1 ELSE 0 END) + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, GREATEST(0, (((date_trunc('day', _hq_scan_upper, 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CASE WHEN _hq_scan_upper > date_trunc('day', _hq_scan_upper, 'UTC') OR _hq_scan_upper_inclusive THEN 1 ELSE 0 END) + 0)) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_source_period FROM _hq_ranges1),
