_hq_leaf1 AS (SELECT _hq_period, _hq_d0, COUNT(_hq_v1) AS _hq_value1 FROM _hq_rows1 GROUP BY _hq_period, _hq_d0),
_hq_skeleton AS (SELECT * FROM _hq_series CROSS JOIN (SELECT DISTINCT _hq_d0 FROM (SELECT _hq_d0 FROM _hq_history0 UNION ALL SELECT _hq_d0 FROM _hq_rows1) AS _hq_populations) AS _hq_combinations),
_hq_lookup0 AS (SELECT s.*, c._hq_eval_end, ROW(s._hq_d0) AS _hq_partition FROM _hq_skeleton AS s INNER JOIN _hq_context0 AS c ON s._hq_period = c._hq_period),
_hq_evaluated0 AS (SELECT s._hq_period, s._hq_d0, m._hq_value0 AS _hq_value0 FROM _hq_lookup0 AS s LEFT JOIN LATERAL (SELECT * FROM _hq_leaf0 AS m WHERE s._hq_partition IS NOT DISTINCT FROM m._hq_partition AND s._hq_eval_end > m._hq_time ORDER BY m._hq_time DESC LIMIT 1) AS m ON TRUE),
_hq_evaluated1 AS (SELECT s.*, coalesce(m._hq_value1, 0) AS _hq_value1 FROM _hq_evaluated0 AS s LEFT JOIN _hq_leaf1 AS m ON s._hq_period = m._hq_period AND (s._hq_d0 IS NOT DISTINCT FROM m._hq_d0)),
