_hq_formula3 AS (SELECT *, (ROUND(CAST("_hq_value2" AS double precision) * CAST(1e2 AS double precision)) / CAST(1e2 AS double precision)) AS "_hq_value3" FROM _hq_formula2),
_hq_values AS (SELECT (v._hq_period AT TIME ZONE 'UTC') AS period, v._hq_d0 AS "status", v._hq_value3 AS "runningAovRounded" FROM _hq_formula3 AS v),
_hq_result AS (SELECT "period", "status", "runningAovRounded" FROM _hq_values UNION ALL SELECT NULL AS "period", NULL AS "status", NULL AS "runningAovRounded" FROM _hq_bounds WHERE 0 + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + 0 + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer) + (SELECT coalesce(max(CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, 1)) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_eval_period AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_eval_period AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)), 0) FROM _hq_context0) + 0 + 0 + (SELECT coalesce(max(0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, GREATEST(0, (((date_trunc('day', _hq_scan_upper, 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CASE WHEN _hq_scan_upper > date_trunc('day', _hq_scan_upper, 'UTC') OR _hq_scan_upper_inclusive THEN 1 ELSE 0 END) + 0)) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_scan_lower, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)), 0) FROM _hq_ranges1) = 1) SELECT "period", "status", "runningAovRounded" FROM _hq_result ORDER BY "period" ASC

